solution.solution.cpp:
#include <cstddef>
#include <mutex>
#include <vector>

class Throttle
{
public:
    explicit Throttle(int intervalMs) : m_interval{ intervalMs } {}

    bool ready(long long nowMs)
    {
        if (m_started && nowMs - m_last < m_interval) return false;
        m_started = true;
        m_last = nowMs;
        m_held = false;
        return true;
    }

    bool finish()
    {
        const bool h{ m_held };
        m_held = false;
        return h;
    }

    void held() { m_held = true; }

private:
    int m_interval;
    long long m_last{ 0 };
    bool m_started{ false };
    bool m_held{ false };
};

template <typename T>
class Batch
{
public:
    bool add(T item)
    {
        std::lock_guard<std::mutex> lock{ m_mutex };
        m_items.push_back(std::move(item));
        if (m_posted) return false;
        m_posted = true;
        return true;
    }

    std::vector<T> take()
    {
        std::lock_guard<std::mutex> lock{ m_mutex };
        std::vector<T> out;
        out.swap(m_items);
        m_posted = false;
        return out;
    }

    std::size_t pending() const
    {
        std::lock_guard<std::mutex> lock{ m_mutex };
        return m_items.size();
    }

private:
    mutable std::mutex m_mutex;
    std::vector<T> m_items;
    bool m_posted{ false };
};

unitTests:
#include <atomic>
#include <string>
#include <thread>
TEST("throttle") {
    Throttle t{ 100 };
    CHECK(t.ready(1000)); CHECK(!t.ready(1050)); t.held(); CHECK(!t.ready(1099)); CHECK(t.ready(1100)); CHECK(!t.finish());
    t.held(); CHECK(t.finish()); CHECK(!t.finish()); CHECK(!t.ready(1150)); CHECK(t.ready(1300));
}
TEST("one message at a time") {
    Batch<std::string> b; CHECK(b.add("a")); CHECK(!b.add("b")); CHECK(!b.add("c")); CHECK_EQ(b.pending(), std::size_t{ 3 });
    const auto got = b.take(); CHECK_EQ(got.size(), std::size_t{ 3 }); CHECK_EQ(got[2], std::string("c")); CHECK_EQ(b.pending(), std::size_t{ 0 });
    CHECK(b.add("d")); CHECK(b.take().size() == 1); CHECK(b.take().empty());
}
TEST("a worker and a UI thread") {
    Batch<int> b; std::atomic<int> messages{ 0 }; std::atomic<bool> done{ false }; long long total = 0; int count = 0;
    std::thread worker([&] { for (int i = 1; i <= 5000; ++i) if (b.add(i)) ++messages; done = true; });
    while (!done || b.pending() > 0) { for (int v : b.take()) { total += v; ++count; } std::this_thread::yield(); }
    worker.join(); for (int v : b.take()) { total += v; ++count; }
    CHECK_EQ(count, 5000); CHECK_EQ(total, 5000LL * 5001 / 2); CHECK(messages.load() >= 1); CHECK(messages.load() <= 5000);
}

